// SPDX-License-Identifier: MIT
pragma solidity 0.8.37;

import {TestBase} from "../TestBase.sol";
import {KilimAuction} from "../../src/KilimAuction.sol";

/// @dev R-01: call gas of a rewarded bid, and the least call gas an outbidding bid needs.
contract R01Test is TestBase {
    event log_named_uint(string key, uint256 val);

    KilimAuction auction;

    function _config() private view returns (KilimAuction.Config memory c) {
        c = config();
    }

    function setUp() public {
        KilimAuction.Config memory c = _config();
        c.reservePrice = 0.01 ether;
        auction = new KilimAuction(c);
        vm.warp(c.startsAt);
        for (uint160 i = 1000; i < 1100; ++i) {
            vm.deal(address(i), 0.01 ether);
            vm.prank(address(i));
            auction.register();
        }
        vm.deal(ALICE, 10 ether);
        vm.deal(BOB, 10 ether);
    }

    function test_firstBidGas() public {
        vm.prank(BOB);
        uint256 g = gasleft();
        auction.bid{value: 0.01 ether}(0.01 ether, 10, 0);
        emit log_named_uint("first bid, 10 symbols", g - gasleft());
        assertEq(auction.symbolCredits(BOB), 10);
    }

    function test_outbidGas() public {
        vm.prank(BOB);
        auction.bid{value: 0.01 ether}(0.01 ether, 10, 0);
        vm.prank(ALICE);
        uint256 g = gasleft();
        auction.bid{value: 0.011 ether}(0.011 ether, 11, 0);
        emit log_named_uint("outbidding bid, EOA refund", g - gasleft());
        assertEq(BOB.balance, 10 ether);
        assertEq(auction.refunds(BOB), 0);
    }

    function _aliceBids(uint256 gasLimit) private returns (bool ok, bytes memory data) {
        vm.prank(ALICE);
        (ok, data) = address(auction).call{value: 0.011 ether, gas: gasLimit}(
            abi.encodeCall(auction.bid, (0.011 ether, 11, 0))
        );
    }

    function test_leastCallGas() public {
        vm.prank(BOB);
        auction.bid{value: 0.01 ether}(0.01 ether, 10, 0);
        uint256 lo = 21_000;
        uint256 hi = 2_000_000;
        while (hi - lo > 1) {
            uint256 mid = (lo + hi) / 2;
            uint256 snap = vm.snapshotState();
            (bool ok,) = _aliceBids(mid);
            vm.revertToState(snap);
            if (ok) hi = mid;
            else lo = mid;
        }
        emit log_named_uint("least call gas, outbidding bid", hi);
        // One gas below: InsufficientGas, not an out-of-gas with a deferred refund.
        uint256 snap2 = vm.snapshotState();
        (bool okLow, bytes memory data) = _aliceBids(hi - 1);
        assertTrue(!okLow);
        assertEq(bytes32(data), bytes32(bytes4(keccak256("InsufficientGas()"))));
        vm.revertToState(snap2);
        // At the limit: the refund is paid, not deferred.
        (bool okAt,) = _aliceBids(hi);
        assertTrue(okAt);
        assertEq(BOB.balance, 10 ether);
        assertEq(auction.refunds(BOB), 0);
        assertEq(auction.refundLiability(), 0);
    }
}
