// SPDX-License-Identifier: MIT
pragma solidity 0.8.37;

import {KilimAuction} from "../../src/KilimAuction.sol";
import {EnglishAuction} from "../../src/auction/EnglishAuction.sol";
import {TestBase} from "../TestBase.sol";

/// @dev R-03: is `block.timestamp < startsAt` in _handleBid reachable once registration is full?
contract R03Test is TestBase {
    KilimAuction internal auction;
    uint256 internal start;

    function setUp() public {
        auction = new KilimAuction(config());
        start = auction.startsAt();
    }

    /// @dev Forward-only clock. Registration is tried at an arbitrary time; whenever it fills,
    ///      the time is already at or past startsAt, and it can only grow. So the clause is false
    ///      at every later bid: the first bid at any later time is accepted.
    function testFuzz_clauseNeverTrueOnForwardClock(uint32 registerAt, uint32 wait) public {
        uint256 t = block.timestamp + uint256(registerAt) % 3 hours;
        vm.warp(t);
        for (uint256 i; i < 100; ++i) {
            address wallet = registrant(i);
            vm.deal(wallet, RESERVE);
            vm.prank(wallet);
            (bool ok,) = address(auction).call(abi.encodeCall(auction.register, ()));
            assertTrue(ok == (t >= start));
        }
        if (t < start) {
            // Not full: the registration gate answers, never the startsAt clause.
            assertEq(auction.registrationCount(), 0);
            vm.deal(ALICE, RESERVE);
            vm.expectRevert(EnglishAuction.RegistrationIncomplete.selector);
            _bid(auction, ALICE, RESERVE);
            return;
        }
        assertEq(auction.registrationCount(), 100);
        vm.warp(t + wait);
        assertTrue(block.timestamp >= start);
        vm.deal(ALICE, RESERVE);
        _bid(auction, ALICE, RESERVE);
        assertEq(auction.highestBidder(), ALICE);
    }

    /// @dev The clause is live bytecode: it answers only when the clock runs backwards, which
    ///      only a cheatcode can do. This is what test/KilimAuction.t.sol testTimeBoundaries does.
    function test_clauseReachedOnlyByBackwardWarp() public {
        _openBidding(auction);
        assertEq(auction.registrationCount(), 100);
        vm.warp(start - 1);
        vm.deal(ALICE, RESERVE);
        vm.expectRevert(EnglishAuction.AuctionNotOpen.selector);
        _bid(auction, ALICE, RESERVE);
    }

    /// @dev `settled` implies `started && block.timestamp >= endsAt` on a forward clock.
    function testFuzz_settledImpliesEnded(uint32 wait) public {
        _openBidding(auction);
        vm.deal(ALICE, RESERVE);
        _bid(auction, ALICE, RESERVE);
        vm.warp(auction.endsAt());
        auction.settle();
        vm.warp(block.timestamp + wait);
        assertTrue(auction.settled());
        assertTrue(auction.highestBidder() != address(0) && block.timestamp >= auction.endsAt());
        vm.deal(BOB, 1 ether);
        vm.expectRevert(EnglishAuction.AuctionNotOpen.selector);
        _bid(auction, BOB, 1 ether);
    }
}

