contract Leader {
    bool public armed;

    function arm(bool on) external {
        armed = on;
    }

    function bid(KilimAuction auction, uint256 amount) external payable {
        auction.bid{value: amount}(amount, 0, 0);
    }

    receive() external payable {
        if (armed) while (gasleft() > 0) {}
    }
}

/// @dev R-07: how much of the 60,000 reserve the first deferred refund uses on today's rules,
///      and what the same path would need with new storage slots at 97,920 gas each.
contract R07Test is TestBase {
    event Measured(string what, uint256 value);

    KilimAuction auction;
    Leader mallory;

    function setUp() public {
        KilimAuction.Config memory c = config();
        c.duration = 1 days;
        c.incrementBps = 1000;
        auction = new KilimAuction(c);
        _openBidding(auction);
        vm.deal(ALICE, 10 ether);
        mallory = new Leader();
        vm.deal(address(mallory), 1 ether);
        mallory.bid(auction, 0.01 ether);
    }

    function _aliceBids(uint256 gasLimit) private returns (bool ok, bytes memory data, uint256 remaining) {
        vm.prank(ALICE);
        (ok, data) = address(auction).call{value: 0.011 ether, gas: gasLimit}(
            abi.encodeCall(auction.bid, (0.011 ether, 0, 0))
        );
        remaining = VmGas(address(vm)).lastCallGas().gasRemaining;
    }

    /// @dev Smallest call gas with which the bid succeeds, to the unit.
    function _minimum() private returns (uint256 hi) {
        uint256 lo = 21_000;
        hi = 2_000_000;
        while (hi - lo > 1) {
            uint256 mid = (lo + hi) / 2;
            uint256 snap = vm.snapshotState();
            (bool ok,,) = _aliceBids(mid);
            vm.revertToState(snap);
            if (ok) hi = mid;
            else lo = mid;
        }
    }

    function testFirstDeferralAgainstTheReserve() public {
        // Unarmed: the floor decides the minimum.
        uint256 minCheap = _minimum();
        mallory.arm(true);
        uint256 minArmed = _minimum();
        emit Measured("minimum call gas, cheap receiver", minCheap);
        emit Measured("minimum call gas, burning receiver", minArmed);
        // The floor binds in both cases, so the two minima are the same number.
        assertEq(minCheap, minArmed);

        // One unit less fails on the floor, not on gas.
        uint256 snap = vm.snapshotState();
        (bool ok, bytes memory data,) = _aliceBids(minArmed - 1);
        assertTrue(!ok);
        assertEq(bytes32(data), bytes32(EnglishAuction.InsufficientGas.selector));
        vm.revertToState(snap);

        // At the minimum the check sees exactly 150,000 + 2,380 + 60,000 = 212,380. The receiver burns
        // its 150,000. What the frame still holds at the end is the unused part of the reserve.
        uint256 remaining;
        (ok,, remaining) = _aliceBids(minArmed);
        assertTrue(ok);
        assertEq(auction.refunds(address(mallory)), 0.01 ether);
        assertEq(auction.refundLiability(), 0.01 ether);
        uint256 afterRefund = 212_380 - 150_000 - remaining;
        emit Measured("left in the frame at the end (headroom)", remaining);
        emit Measured("used after the failed refund, cancun", afterRefund);
        assertTrue(afterRefund <= 62_380);

        // The two first-time slot writes cost 22,100 each today (20,000 set + 2,100 cold).
        // With a new slot at 97,920 state gas taken from gasleft, the same path needs:
        uint256 repriced = afterRefund - 2 * 20_000 + 2 * 97_920;
        emit Measured("same path with two new slots at 97,920", repriced);
        assertTrue(repriced > 62_380);
    }
}

