        while (hi - lo > 1) {
            uint256 mid = (lo + hi) / 2;
            uint256 snap = vm.snapshotState();
            (bool ok,) = _send(from, value, data, mid);
            vm.revertToState(snap);
            if (ok) hi = mid;
            else lo = mid;
