import {Kilim} from "../../src/Kilim.sol";

/// @dev A pool that wins and can hold the 1/1, but has no way to call claimPrize.
contract R10Pool is IERC721Receiver {
    function bid(KilimAuction auction, uint256 amount) external payable {
        auction.bid{value: amount}(amount, 0, 0);
    }

    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }
}

/// @dev Not the winner. Holds four symbols and settles from inside Kilim's weave callback.
contract R10Griefer is IERC721Receiver {
    KilimAuction auction;
    bool armed;

    constructor(KilimAuction a) {
        auction = a;
    }

    function bid(uint256 amount) external payable {
        auction.bid{value: amount}(amount, 0, 0);
    }

    function claim(uint256 n) external {
        auction.claimSymbols(n, address(this));
    }

    function attack(uint256[] calldata cells) external {
        armed = true;
        auction.collection().weave(cells, 2, 2, "flat/ink");
    }

    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {
        if (armed) {
            armed = false;
            auction.settle();
        }
        return IERC721Receiver.onERC721Received.selector;
    }

    receive() external payable {}
}

contract R10Test is TestBase {
