```solidity
// SPDX-License-Identifier: MIT
pragma solidity 0.8.37;

import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {TestBase} from "../TestBase.sol";
import {KilimAuction} from "../../src/KilimAuction.sol";
import {EnglishAuction} from "../../src/auction/EnglishAuction.sol";

/// @dev A winner whose NFT callback burns a set amount of gas, and a leader whose ETH receiver does.
contract HungryWallet is IERC721Receiver {
    uint256 public immutable nftBurn;
    uint256 public immutable ethBurn;
    uint256 public entryGas;

    constructor(uint256 nftBurn_, uint256 ethBurn_) {
        nftBurn = nftBurn_;
        ethBurn = ethBurn_;
    }

    function bid(KilimAuction auction, uint256 amount) external payable {
        auction.bid{value: amount}(amount, 0, 0);
    }

    function _burn(uint256 amount) private view {
        uint256 start = gasleft();
        while (start - gasleft() < amount) {}
    }

    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {
        if (nftBurn == 0) entryGas = gasleft();
        _burn(nftBurn);
        return IERC721Receiver.onERC721Received.selector;
    }

    receive() external payable {
        _burn(ethBurn);
    }
}

contract R12Test is TestBase {
    KilimAuction auction;

    function setUp() public {
        KilimAuction.Config memory c = config();
        c.duration = 1 days;
        c.incrementBps = 1000;
        auction = new KilimAuction(c);
        _openBidding(auction);
        vm.deal(ALICE, 10 ether);
    }

    function _sweep(uint256 burn, uint256 step) private {
        HungryWallet pool = new HungryWallet(burn, 0);
        vm.deal(address(pool), 1 ether);
        pool.bid(auction, 0.01 ether);
        vm.warp(auction.endsAt());
        for (uint256 gasLimit = 100_000; gasLimit <= 900_000; gasLimit += step) {
            uint256 snap = vm.snapshotState();
            (bool ok,) = address(auction).call{gas: gasLimit}(abi.encodeCall(auction.settle, ()));
            if (ok) {
                assertTrue(auction.prizeClaimed());
                assertEq(auction.collection().ownerOf(1), address(pool));
            } else {
                assertTrue(!auction.settled());
            }
            vm.revertToState(snap);
        }
        auction.settle();
        assertEq(auction.collection().ownerOf(1), address(pool));
    }

    /// The finding's suggested test, as written: 380,000 burned, 4k steps.
    function testAWinnerNeedingMostOfThePrizeCapIsDeliveredAtAnyGasLimit() public {
        _sweep(380_000, 4_000);
    }

    /// A tighter variant: the callback needs all but a sliver of what a full PRIZE_GAS gives it.
    function testAWinnerNeedingNearlyAllOfThePrizeCapIsDeliveredAtAnyGasLimit() public {
        _sweep(400_000, 1_000);
    }

    /// Measurement only: gas the receiver callback sees when deliverPrize has its full allowance.
    function testMeasureCallbackEntryGas() public {
        HungryWallet pool = new HungryWallet(0, 0);
        vm.deal(address(pool), 1 ether);
        pool.bid(auction, 0.01 ether);
        vm.warp(auction.endsAt());
        auction.settle();
        // 404,141 on the real code: a full PRIZE_GAS less the mint.
        assertTrue(pool.entryGas() > 402_000);
    }

    function testAReceiverNeedingMostOfTheRefundCapIsStillPaid() public {
        HungryWallet leader = new HungryWallet(0, 120_000);
        vm.deal(address(leader), 0.01 ether);
        leader.bid(auction, 0.01 ether);
        assertEq(address(leader).balance, 0);
        vm.expectEmit();
        emit EnglishAuction.RefundPaid(address(leader), 0.01 ether);
        vm.prank(ALICE);
        auction.bid{value: 0.011 ether}(0.011 ether, 0, 0);
        assertEq(address(leader).balance, 0.01 ether);
        assertEq(auction.refunds(address(leader)), 0);
        assertEq(auction.refundLiability(), 0);
    }
}
