// SPDX-License-Identifier: MIT
pragma solidity 0.8.37;

import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {KilimAuction} from "../../src/KilimAuction.sol";
import {Kilim} from "../../src/Kilim.sol";
import {TestBase} from "../TestBase.sol";
import {Receiver} from "../mocks/Receiver.sol";

/// @dev Calls back into a target from its ETH receiver. fire() makes the same call from outside.
contract R14Sink {
    address public target;
    bytes public payload;
    bool public callbackSucceeded;

    function hook(address target_, bytes calldata payload_) external {
        target = target_;
        payload = payload_;
    }

    function fire() external returns (bool ok) {
        (ok,) = target.call(payload);
    }

    receive() external payable {
        if (target != address(0)) (callbackSucceeded,) = target.call(payload);
    }
}

contract R14Test is TestBase {
    KilimAuction internal auction;
    Kilim internal nft;

    function setUp() public {
        auction = new KilimAuction(config());
        nft = auction.collection();
        vm.deal(ALICE, 1e30);
        _openBidding(auction);
    }

    /// @dev The proceeds recipient holds symbol credits and tries to claim them from inside the
    ///      payout. The guard stops it; the same call from outside the payout succeeds.
    function testProceedsRecipientCannotReenter() public {
        R14Sink sink = new R14Sink();
        vm.deal(address(sink), 1e30);
        _bid(auction, address(sink), 25 * UNIT);
        _bid(auction, ALICE, 30 * UNIT);
        vm.warp(auction.endsAt());
        auction.settle();
        sink.hook(address(auction), abi.encodeCall(auction.claimSymbols, (1, CAROL)));
        uint256 before = address(sink).balance;
        vm.prank(TREASURY);
        auction.withdrawProceeds(address(sink));
        assertEq(address(sink).balance, before + 30 * UNIT);
        assertTrue(!sink.callbackSucceeded());
        assertEq(auction.symbolCredits(address(sink)), 25);
        assertEq(nft.balanceOf(CAROL), 0);
        assertTrue(sink.fire());
        assertEq(auction.symbolCredits(address(sink)), 24);
        assertEq(nft.balanceOf(CAROL), 1);
    }

    /// @dev A winner with a waiting refund tries to withdraw it from the NFT callback inside
    ///      claimPrize. The guard stops it; the same call from outside the claim succeeds.
    function testClaimedPrizeCallbackCannotReenter() public {
        Receiver receiver = new Receiver();
        vm.deal(address(receiver), 1e30);
        _bid(auction, address(receiver), 25 * UNIT);
        // Receiver has no ETH receiver, so its refund waits.
        _bid(auction, ALICE, 30 * UNIT);
        assertEq(auction.refunds(address(receiver)), 25 * UNIT);
        _bid(auction, address(receiver), 40 * UNIT);
        receiver.configure(true, address(0), "");
        vm.warp(auction.endsAt());
        auction.settle();
        assertTrue(!auction.prizeClaimed());
        bytes memory withdraw = abi.encodeCall(auction.withdrawRefund, (CAROL));
        receiver.configure(false, address(auction), withdraw);
        vm.prank(address(receiver));
        auction.claimPrize(address(receiver));
        assertEq(nft.ownerOf(1), address(receiver));
        assertTrue(!receiver.callbackSucceeded());
        assertEq(auction.refunds(address(receiver)), 25 * UNIT);
        assertEq(CAROL.balance, 0);
        receiver.execute(address(auction), withdraw);
        assertEq(auction.refunds(address(receiver)), 0);
        assertEq(CAROL.balance, 25 * UNIT);
    }
}

