// SPDX-License-Identifier: MIT
pragma solidity 0.8.37;

import {TestBase} from "../TestBase.sol";
import {KilimAuction} from "../../src/KilimAuction.sol";
import {EnglishAuction} from "../../src/auction/EnglishAuction.sol";
import {Kilim} from "../../src/Kilim.sol";

/// @dev A leader that, when its refund arrives, tries to register and records why that failed.
contract ReentrantRegistrant {
    KilimAuction internal immutable auction;
    bytes4 public registerError;
    bytes4 public registerForError;

    constructor(KilimAuction auction_) {
        auction = auction_;
    }

    function bid(uint256 amount) external payable {
        auction.bid{value: amount}(amount, 0, 0);
    }

    receive() external payable {
        try auction.register() {}
        catch (bytes memory reason) {
            registerError = bytes4(reason);
        }
        try auction.registerFor(address(this), type(uint256).max, "") {}
        catch (bytes memory reason) {
            registerForError = bytes4(reason);
        }
    }
}

/// @dev A leader whose refund burns the whole allowance, so the refund is deferred at full cost.
contract RefundBurner {
    function bid(KilimAuction auction, uint256 amount) external payable {
        auction.bid{value: amount}(amount, 0, 0);
    }

    receive() external payable {
        while (gasleft() > 0) {}
    }
}

contract R19Test is TestBase {
    bytes4 private constant REENTRANT = bytes4(keccak256("ReentrancyGuardReentrantCall()"));

    KilimAuction private auction;

    function setUp() public {
        auction = new KilimAuction(config());
        _openBidding(auction);
    }

    // X04, X05: with nonReentrant the nested register calls fail on the guard. Without it they would
    // fail on RegistrationClosed and InvalidRegistrationSignature. State is the same either way.
    function testRegisterInsideRefundFailsOnTheGuard() public {
        ReentrantRegistrant leader = new ReentrantRegistrant(auction);
        _fund(address(leader), RESERVE);
        leader.bid(RESERVE);
        _fund(BOB, 2 * RESERVE);
        _bid(auction, BOB, 2 * RESERVE);
        assertEq(address(leader).balance, RESERVE);
        assertTrue(leader.registerError() == REENTRANT);
        assertTrue(leader.registerForError() == REENTRANT);
        assertTrue(!auction.registered(address(leader)));
    }

    // X11: a bid that is both underpaid and below the refund gas floor names the payment, because
    // the payment check runs first. Swapped, it would name the gas.
    function testUnderpaidLowGasBidNamesThePayment() public {
        _fund(ALICE, RESERVE);
        _bid(auction, ALICE, RESERVE);
        _fund(BOB, 2 * RESERVE);
        vm.prank(BOB);
        (bool ok, bytes memory reason) = address(auction).call{value: 2 * RESERVE - 1, gas: 180_000}(
            abi.encodeCall(KilimAuction.bid, (2 * RESERVE, 0, 0))
        );
        assertTrue(!ok);
        assertTrue(bytes4(reason) == EnglishAuction.IncorrectPayment.selector);
        // The same gas with the right payment stops at the floor, so 180,000 is below it.
        vm.prank(BOB);
        (ok, reason) = address(auction).call{value: 2 * RESERVE, gas: 180_000}(
            abi.encodeCall(KilimAuction.bid, (2 * RESERVE, 0, 0))
        );
        assertTrue(!ok);
        assertTrue(bytes4(reason) == EnglishAuction.InsufficientGas.selector);
    }

    // E13: the zero address has no code and ecrecover never yields it, so the signature check alone
    // refuses it with the same error.
    function testZeroAddressNeverPassesTheSignatureCheck() public {
        bytes memory junk = abi.encodePacked(bytes32(uint256(1)), bytes32(uint256(1)), uint8(27));
        vm.expectRevert(EnglishAuction.InvalidRegistrationSignature.selector);
        auction.registerFor(address(0), type(uint256).max, junk);
        vm.expectRevert(EnglishAuction.InvalidRegistrationSignature.selector);
        auction.registerFor(address(0), type(uint256).max, "");
    }

    // E07, K02, K03: each config is refused by a neighbouring check as well.
    function testRedundantConstructorChecksHaveBackups() public {
        // duration 0 forces extensionWindow 0 or extensionWindow > duration.
        for (uint64 window = 0; window < 3; ++window) {
            KilimAuction.Config memory c = config();
            c.duration = 0;
            c.extensionWindow = window;
            assertTrue(window == 0 || window > c.duration);
        }
        // symbolCap 0 forces maxSymbolsPerBid 0 or maxSymbolsPerBid > symbolCap.
        // The collection itself refuses a cap above uint32 max less the first symbol id.
        Kilim nft = auction.collection();
        uint256 bound = type(uint32).max - nft.FIRST_SYMBOL_ID();
        vm.expectRevert(Kilim.InvalidConfiguration.selector);
        this.newKilimWithCap(bound + 1);
        this.newKilimWithCap(bound);
        assertTrue(Kilim.InvalidConfiguration.selector == EnglishAuction.InvalidConfiguration.selector);
        assertTrue(Kilim.InvalidRecipient.selector == EnglishAuction.InvalidRecipient.selector);
    }

    function newKilimWithCap(uint256 cap) external returns (Kilim) {
        KilimAuction.Config memory c = config();
        return new Kilim(
            address(this), PAGE_OWNER, TREASURY, cap, c.motifCount, c.maxCells, c.geometryHash, c.rendererHash,
            mockRenderer
        );
    }

    // E28: for every whole-unit bid the increment divides exactly, so the rounding mode is unused.
    function testFuzzIncrementIsExactForWholeUnitBids(uint128 units, uint16 bps) public pure {
        bps = uint16(bound16(bps));
        uint256 highest = uint256(units) * UNIT;
        assertEq(mulmod(highest, bps, 10_000), 0);
    }

    function bound16(uint16 x) private pure returns (uint256) {
        return 1 + (uint256(x) % 10_000);
    }

    // E56: after settlement a bid is refused by the time check alone, and endsAt cannot move.
    function testAfterSettlementTheTimeCheckAlreadyRefusesBids() public {
        _fund(ALICE, RESERVE);
        _bid(auction, ALICE, RESERVE);
        vm.warp(auction.endsAt());
        auction.settle();
        assertTrue(auction.highestBidder() != address(0) && block.timestamp >= auction.endsAt());
        _fund(BOB, 2 * RESERVE);
        vm.expectRevert(EnglishAuction.AuctionNotOpen.selector);
        _bid(auction, BOB, 2 * RESERVE);
    }

    // K37: the collection refuses the same three recipients with the same error.
    function testCollectionRefusesTheSamePrizeRecipients() public {
        Kilim nft = auction.collection();
        address[3] memory bad = [address(0), address(auction), address(nft)];
        for (uint256 i; i < 3; ++i) {
            vm.prank(address(auction));
            vm.expectRevert(EnglishAuction.InvalidRecipient.selector);
            nft.mintMasterpiece(bad[i]);
        }
    }

    // E75b, E75c: the gas a bid keeps after the refund self-call, measured at the floor with a
    // leader that burns the whole allowance and a first-time deferred refund (two fresh slots).
    function testDeferredRefundFitsInsideTheFloor() public {
        RefundBurner leader = new RefundBurner();
        _fund(address(leader), RESERVE);
        leader.bid{value: RESERVE}(auction, RESERVE);
        _fund(BOB, 2 * RESERVE);
        bytes memory data = abi.encodeCall(KilimAuction.bid, (2 * RESERVE, 0, 0));
        // Find the least gas at which the bid succeeds.
        uint256 low = 100_000;
        uint256 high = 1_000_000;
        while (high - low > 1) {
            uint256 mid = (low + high) / 2;
            uint256 snap = vm.snapshotState();
            vm.prank(BOB);
            (bool ok,) = address(auction).call{value: 2 * RESERVE, gas: mid}(data);
            vm.revertToState(snap);
            if (ok) high = mid;
            else low = mid;
        }
        // One gas below the least it stops at the floor; it never runs out after the self-call.
        uint256 snap2 = vm.snapshotState();
        vm.prank(BOB);
        (bool ok2, bytes memory reason) = address(auction).call{value: 2 * RESERVE, gas: low}(data);
        assertTrue(!ok2 && bytes4(reason) == EnglishAuction.InsufficientGas.selector);
        vm.revertToState(snap2);
        vm.prank(BOB);
        uint256 before = gasleft();
        (ok2,) = address(auction).call{value: 2 * RESERVE, gas: high}(data);
        uint256 used = before - gasleft();
        assertTrue(ok2);
        assertEq(auction.refunds(address(leader)), RESERVE);
        emit Measured("least gas for the bid call", high);
        emit Measured("gas used by that call (caller view)", used);
        emit Measured("unused of the least gas", high > used ? high - used : 0);
    }

    event Measured(string what, uint256 value);
}
